const R_LINE: [number, number][] = [[0.0, 322], [0.3, 336], [1.5, 374], [6.6, 636.4], [9.6, 775]]
const along = (line: [number, number][]) => piecewise(line.map(([x, y]) => [y, x]))

const norm = (a: V3): V3 => { const l = Math.hypot(...a) || 1; return [a[0] / l, a[1] / l, a[2] / l] }

/** A vertical band in the plane x = u between two curves of y, facing s (±1 in x). */
function wall(p: Part, u: number, s: number, ys: number[], top: (y: number) => number, bot: (y: number) => number) {
  for (let i = 0; i < ys.length - 1; i++) {
    const a = ys[i], b = ys[i + 1]
    face(p, [u, a, bot(a)], [u, b, bot(b)], [u, b, top(b)], [u, a, top(a)], [s, 0, 0])
  }
}
/** A strip from x0 to x1 following z(y), facing up or down. */
function flat(p: Part, x0: number, x1: number, ys: number[], z: (y: number) => number, up: boolean) {
  for (let i = 0; i < ys.length - 1; i++) {
    const a = ys[i], b = ys[i + 1]
    face(p, [x0, a, z(a)], [x1, a, z(a)], [x1, b, z(b)], [x0, b, z(b)], norm([0, up ? -(z(b) - z(a)) : z(b) - z(a), up ? b - a : -(b - a)]))
  }
}
/** A box along y from a to b, x0..x1, between bot(y) and top(y); `ends` adds the end faces. */
function beam(p: Part, x0: number, x1: number, ys: number[], top: (y: number) => number, bot: (y: number) => number, ends = false, bottom = true) {
  wall(p, x0, -1, ys, top, bot)
  wall(p, x1, 1, ys, top, bot)
  flat(p, x0, x1, ys, top, true)
  if (bottom) flat(p, x0, x1, ys, bot, false)
  if (ends) for (const [y, s] of [[ys[0], -1], [ys[ys.length - 1], 1]] as [number, number][])
    face(p, [x0, y, bot(y)], [x1, y, bot(y)], [x1, y, top(y)], [x0, y, top(y)], [0, s, 0])
}
/** A plain box. */
function box(p: Part, x0: number, x1: number, y0: number, y1: number, z0: number, z1: number, bottom = false) {
  beam(p, x0, x1, [y0, y1], () => z1, () => z0, true, bottom)
}
/** Round-headed openings (shaded panels) set just proud of a wall face at x = u. */
function openings(p: Part, u: number, s: number, y0: number, y1: number, pitch: number, w: number, sill: (y: number) => number, h: number, segs = 3) {
  const n = Math.max(1, Math.round((y1 - y0) / pitch)), step = (y1 - y0) / n, r = w / 2, x = u + s * 0.06, nn: V3 = [s, 0, 0]
  for (let k = 0; k < n; k++) {
    const yc = y0 + (k + 0.5) * step, z0 = sill(yc), zs = z0 + h - r
    face(p, [x, yc - r, z0], [x, yc + r, z0], [x, yc + r, zs], [x, yc - r, zs], nn)
    const head: V3[] = Array.from({ length: segs + 1 }, (_, j) => { const t = Math.PI - (Math.PI * j) / segs; return [x, yc + r * Math.cos(t), zs + r * Math.sin(t)] as V3 })
    for (let j = 0; j < segs; j++) {
      const c: V3 = [x, yc, zs]
      if (s > 0) p.tri(c, head[j + 1], head[j]); else p.tri(c, head[j], head[j + 1])
    }
  }
}
/** Points spread over [a, b] about `step` apart. */
const st = (a: number, b: number, step: number) => stations(a, b, step)

function build(D: boolean) {
  const stone = new Part(), granite = new Part(), steel = new Part(), brick = new Part(), shade = new Part(), lamps = new Part()
  const fasciaBot = (y: number) => road(y) - FASCIA

  // ---- Road deck: fascia, corbelled underside, railing, the south sidewalk --------------------------------------
  {
    const west = st(END_W, WT - 5, 22), east = st(WT - 5, ET + 5, 22)
    for (const [ys, h, w] of [[west, AH, AW], [east, DH, HW]] as [number[], number, number][]) {
      for (const s of SIDES) {
        const u = XC + s * h
        wall(granite, u, s, ys, (y) => road(y) + 0.1, fasciaBot)                                      // fascia
        wall(steel, u - s * 0.05, s, ys, (y) => road(y) + 1.15, (y) => road(y) + 0.1)                 // lattice railing (solid band)
        flat(granite, Math.min(u, XC + s * w), Math.max(u, XC + s * w), ys, fasciaBot, false)         // underside of the overhang
      }
      // The south sidewalk (way 648267667): its surface and its kerb, the model's own.
      flat(granite, XC + 6.6, XC + h - 0.1, ys, (y) => road(y) + 0.2, true)
      wall(granite, XC + 6.6, -1, ys, (y) => road(y) + 0.2, (y) => road(y))
      if (D) wall(steel, XC + 6.6, -1, ys, (y) => road(y) + 1.2, (y) => road(y) + 0.2)              // the path's inner railing
    }
    // The end abutment's face at the landing, across the deck, 0.3 m under the roadway.
    footedWall(stone, [XC - AH, END_W], [XC + AH, END_W], gnd, () => road(END_W) - 0.3, [0, -1, 0], 4)
  }

  // ---- MetroLink lower deck: its floor (track surface) and underside, everywhere under the road ------------------
  {
    const ys = st(END_W + 70, ET + 5, 24)
    flat(granite, XC - 6.4, XC + 6.4, ys, rail, true)
    flat(granite, XC - 7.6, XC + 7.6, ys, (y) => rail(y) - 1.0, false)
  }

  // ---- West end abutment, from the landing to 2nd Street: solid stone ---------------------------------------
  for (const s of SIDES) footedWall(stone, [XC + s * AH, END_W], [XC + s * AH, CROSS[0][0]], gnd, (_x, y) => Math.max(fasciaBot(y), gnd(XC + s * AH, y) + 0.05), [s, 0, 0], 8)
  footedWall(stone, [XC - AH, CROSS[0][0]], [XC + AH, CROSS[0][0]], gnd, () => rail(CROSS[0][0]) - 1.6, [0, 1, 0], 4)

  // ---- West approach blocks: limestone walls, brick arcade, end faces at the streets -----------------------------
  for (const [a, b] of BLOCKS) {
    const ys = st(a, b, 12)
    for (const s of SIDES) {
      const u = XC + s * AW
      footedWall(stone, [u, a], [u, b], gnd, (_x, y) => rail(y) - 0.3, [s, 0, 0], 8)
      wall(brick, u, s, ys, fasciaBot, (y) => rail(y) - 0.3)
      openings(shade, u, s, a + 0.6, b - 0.6, 3.0, 2.0, (y) => rail(y) + 0.2, 3.3, D ? 4 : 3)
      if (D) for (const y of st(a + 1, b - 1, 3.0)) box(granite, Math.min(u, XC + s * (AH - 0.1)), Math.max(u, XC + s * (AH - 0.1)), y - 0.35, y + 0.35, fasciaBot(y) - 0.9, fasciaBot(y)) // corbels
    }
    // End faces toward the streets, up to the girder seats.
    for (const [y, n] of [[a, -1], [b, 1]] as [number, number][]) if (y > WT - 6) continue; else footedWall(stone, [XC - AW, y], [XC + AW, y], gnd, () => rail(y) - 1.6, [0, n, 0], 4)
  }
  // Street spans: the rail deck's plate girders, the lower deck seen through above them.
  for (const [a, b] of CROSS) {
    const ys = [a, b]
    for (const s of SIDES) {
      beam(steel, XC + s * AW - 0.5, XC + s * AW + 0.5, ys, (y) => rail(y) + 0.3, (y) => rail(y) - 1.6, false)
      wall(shade, XC + s * (AW - 1.2), s, ys, fasciaBot, (y) => rail(y) + 0.3)
    }
  }

  // ---- Towers and abutment piers (granite) ------------------------------------------------------------------------
  const tower = (yc: number, hl: number, hx: number, top: number) => {
    footedLoft(granite, gnd, [
      { plan: chamferedRect(XC - hx, XC + hx, yc - hl, yc + hl, 0.5), z: 'ground' },
      { plan: chamferedRect(XC - hx, XC + hx, yc - hl, yc + hl, 0.5), z: top - 1.6 },
      { plan: chamferedRect(XC - hx - 0.4, XC + hx + 0.4, yc - hl - 0.4, yc + hl + 0.4, 0.7), z: top - 1.2 },
      { plan: chamferedRect(XC - hx - 0.4, XC + hx + 0.4, yc - hl - 0.4, yc + hl + 0.4, 0.7), z: top },
    ], 6)
  }
  tower(WT, 5, 9.4, road(WT) + 1.4)
  tower(ET, 5, 9.4, road(ET) + 1.4)
  for (const yc of [WA, EA]) {
    // A battered base on the levee, then the shaft to the parapet.
    footedLoft(granite, gnd, [
      { plan: chamferedRect(XC - 10.4, XC + 10.4, yc - 8, yc + 8, 1.2), z: 'ground' },
      { plan: chamferedRect(XC - 9.4, XC + 9.4, yc - 7, yc + 7, 0.6), z: 10.5 },
      { plan: chamferedRect(XC - 9.4, XC + 9.4, yc - 7, yc + 7, 0.6), z: road(yc) - 0.2 },
      { plan: chamferedRect(XC - 9.8, XC + 9.8, yc - 7.4, yc + 7.4, 0.8), z: road(yc) + 0.2 },
      { plan: chamferedRect(XC - 9.8, XC + 9.8, yc - 7.4, yc + 7.4, 0.8), z: road(yc) + 1.4 },
    ], 6)
  }

  // ---- River piers: pale masonry bases in the water, granite shafts, pedestals past the deck --------------------
  for (const yc of [WP, EP]) {
    footedLoft(stone, gnd, [
      { plan: chamferedRect(XC - 13, XC + 13, yc - 9, yc + 9, 4), z: 'ground' },
      { plan: chamferedRect(XC - 12.6, XC + 12.6, yc - 8.6, yc + 8.6, 3.8), z: SPRING - 0.6 },
      { plan: chamferedRect(XC - 12.2, XC + 12.2, yc - 8.2, yc + 8.2, 3.6), z: SPRING },
    ], 8)
    footedLoft(granite, gnd, [
      { plan: chamferedRect(XC - 11.5, XC + 11.5, yc - 5, yc + 5, 0.6), z: SPRING },
      { plan: chamferedRect(XC - 11.5, XC + 11.5, yc - 5, yc + 5, 0.6), z: fasciaBot(yc) },
    ], 30)
    for (const s of SIDES) {
      const x0 = XC + s * (DH + 0.05), x1 = XC + s * 11.5
      box(granite, Math.min(x0, x1), Math.max(x0, x1), yc - 4.6, yc + 4.6, fasciaBot(yc) - 0.6, road(yc) + 0.1)
    }
  }

  // ---- Arcades: five bays between tower and abutment, round arches on piers ------------------------------------
  const arcade = (y0: number, y1: number, flatFirst: boolean) => {
    const pier = 3.4, span = (y1 - y0 - 4 * pier) / 5, r = span / 2, zs = ARC_CROWN - r
    for (let k = 0; k < 5; k++) {
      const a = y0 + k * (span + pier), b = a + span, yc = (a + b) / 2
      const isFlat = flatFirst && k === 0
      const intra = (y: number) => (isFlat ? zs : zs + Math.sqrt(Math.max(0, r * r - (y - yc) ** 2)))
      const ys = isFlat ? [a, b] : st(a, b, r / 4)
      for (const s of SIDES) wall(stone, XC + s * HW, s, ys, fasciaBot, intra)
      flat(stone, XC - HW, XC + HW, ys, intra, false)
      // Piers between bays: faces on both sides, and their sides inside the openings.
      if (k < 4) {
        for (const s of SIDES) footedWall(stone, [XC + s * HW, b], [XC + s * HW, b + pier], gnd, (_x, y) => fasciaBot(y), [s, 0, 0], 4)
        footedWall(stone, [XC - HW, b], [XC + HW, b], gnd, () => zs, [0, -1, 0], 6)
        footedWall(stone, [XC - HW, b + pier], [XC + HW, b + pier], gnd, () => zs, [0, 1, 0], 6)
      }
    }
    for (const s of SIDES) openings(shade, XC + s * HW, s, y0 + 0.4, y1 - 0.4, 3.1, 1.9, (y) => rail(y) + 0.3, 3.2, D ? 4 : 3)
    // A string course at the rail floor, both faces.
    if (D) for (const s of SIDES) wall(granite, XC + s * (HW + 0.15), s, st(y0, y1, 20), (y) => rail(y) - 0.2, (y) => rail(y) - 0.7)
  }
  arcade(WT + 5, WA - 7, true)
  arcade(EA + 7, ET - 5, false)

  // ---- The arch spans -------------------------------------------------------------------------------------------
  for (const [a, b, crown] of SPANS) {
    const m = (a + b) / 2, half = (b - a) / 2, rise = crown - SPRING
    const R = (half * half + rise * rise) / (2 * rise), zc = crown - R
    const lower = (y: number) => zc + Math.sqrt(Math.max(0, R * R - (y - m) ** 2))
    const upper = (y: number) => lower(y) + RIB
    const n = D ? 28 : 16, ys = st(a, b, (b - a) / n)
    for (const off of RIBS) {
      const u = XC + off, outer = Math.abs(off) > 5, s = Math.sign(off)
      if (!D) {
        // Low: each rib a solid band from tube to tube, with its soffit (and top, on the outer ribs).
        wall(steel, u, s, ys, (y) => upper(y) + 0.35, (y) => lower(y) - 0.35)
        flat(steel, u - 0.4, u + 0.4, ys, (y) => lower(y) - 0.35, false)
        if (outer) flat(steel, u - 0.4, u + 0.4, ys, (y) => upper(y) + 0.35, true)
      } else {
        // Detail: the two tubes as square chords and the lattice web between them.
        for (const f of [lower, upper]) beam(steel, u - 0.35, u + 0.35, ys, (y) => f(y) + 0.35, (y) => f(y) - 0.35)
        for (let i = 0; i < ys.length - 1; i++) {
          const y0 = ys[i], y1 = ys[i + 1], ym = (y0 + y1) / 2
          strip(steel, [u, y0, lower(y0) + 0.3], [u, ym, upper(ym) - 0.3], 0.28, [1, 0, 0])
          strip(steel, [u, ym, upper(ym) - 0.3], [u, y1, lower(y1) + 0.3], 0.28, [1, 0, 0])
        }
      }
    }
    // Spandrel posts from the ribs' top up to the lower deck; X bracing between them on the outer ribs (detail).
    const panel = D ? 5.2 : 10.4, posts = st(a + 2.6, b - 2.6, panel)
    const ribs = D ? RIBS : [RIBS[0], RIBS[3]]
    for (const off of ribs) {
      const u = XC + off
      posts.forEach((y, i) => {
        const z0 = upper(y) + 0.35, z1 = rail(y) - 1.0
        if (z1 - z0 > 0.6) strip(steel, [u, y, z0], [u, y, z1], D ? 0.4 : 0.6, [1, 0, 0])
        if (D && Math.abs(off) > 5 && i < posts.length - 1) {
          const y2 = posts[i + 1], z2 = upper(y2) + 0.35, z3 = rail(y2) - 1.0
          if (z1 - z0 > 1.2 && z3 - z2 > 1.2) {
            strip(steel, [u, y, z0], [u, y2, z3], 0.22, [1, 0, 0])
            strip(steel, [u, y, z1], [u, y2, z2], 0.22, [1, 0, 0])
          }
        }
      })
    }
  }
  // The lower deck's side girders over the river, under the road deck's fascia.
  {
    const a = WA + 7, b = EA - 7, ys = st(a, b, D ? 5.2 : 24)
    for (const s of SIDES) {
      const u = XC + s * 7.6
      if (!D) wall(steel, u, s, ys, fasciaBot, (y) => rail(y) - 1.0)
      else {
        wall(steel, u, s, ys, fasciaBot, (y) => fasciaBot(y) - 0.5)
        wall(steel, u, s, ys, (y) => rail(y) - 0.4, (y) => rail(y) - 1.0)
        for (let i = 0; i < ys.length - 1; i++) {
          const y0 = ys[i], y1 = ys[i + 1]
          strip(steel, [u, y0, rail(y0) - 0.4], [u, y0, fasciaBot(y0) - 0.5], 0.3, [1, 0, 0])
          strip(steel, [u, y0, rail(y0) - 0.4], [u, y1, fasciaBot(y1) - 0.5], 0.16, [1, 0, 0])
          strip(steel, [u, y0, fasciaBot(y0) - 0.5], [u, y1, rail(y1) - 0.4], 0.16, [1, 0, 0])
        }
      }
    }
  }

  // ---- East approach: two roadway decks around the open rail deck, on concrete bents ------------------------------
  {
    const nx = along(N_LINE), sx = along(S_LINE), rx = along(R_LINE)
    const decks: { x: (y: number) => number; z: (y: number) => number; l: number; r: number; y0: number; y1: number; depth: number; walk?: boolean }[] = [
      { x: nx, z: roadN, l: -4.2, r: 4.2, y0: ET + 5, y1: 628, depth: 1.6 },
      { x: sx, z: roadS, l: -4.2, r: 7.0, y0: ET + 5, y1: 628, depth: 1.6, walk: true },
      { x: rx, z: railE, l: -5.0, r: 5.0, y0: ET + 5, y1: 776, depth: 1.8 },
    ]
    for (const [k, d] of decks.entries()) {
      const ys = st(d.y0, d.y1, 24)
      const isRail = k === 2
      const top = (y: number) => d.z(y) + (isRail ? 0.25 : 0.1)
      const bot = (y: number) => d.z(y) - d.depth
      for (const [off, s] of [[d.l, -1], [d.r, 1]] as [number, number][]) {
        for (let i = 0; i < ys.length - 1; i++) {
          const a = ys[i], b = ys[i + 1], xa = d.x(a) + off, xb = d.x(b) + off
          face(isRail ? steel : granite, [xa, a, bot(a)], [xb, b, bot(b)], [xb, b, top(b)], [xa, a, top(a)], [s, 0, 0])
          face(isRail ? steel : granite, [xa, a, top(a)], [xb, b, top(b)], [xb, b, top(b) + 0.9], [xa, a, top(a) + 0.9], [s, 0, 0])
        }
      }
      for (let i = 0; i < ys.length - 1; i++) {
        const a = ys[i], b = ys[i + 1]
        face(granite, [d.x(a) + d.l, a, bot(a)], [d.x(a) + d.r, a, bot(a)], [d.x(b) + d.r, b, bot(b)], [d.x(b) + d.l, b, bot(b)], [0, 0, -1])
        if (isRail) face(granite, [d.x(a) + d.l, a, d.z(a)], [d.x(a) + d.r, a, d.z(a)], [d.x(b) + d.r, b, d.z(b)], [d.x(b) + d.l, b, d.z(b)], [0, 0, 1])
        if (d.walk) face(granite, [d.x(a) + 4.3, a, d.z(a) + 0.2], [d.x(a) + d.r, a, d.z(a) + 0.2], [d.x(b) + d.r, b, d.z(b) + 0.2], [d.x(b) + 4.3, b, d.z(b) + 0.2], [0, 0, 1])
      }
      // Landing: an abutment face down to the ground under the deck's end.
      const ye = d.y1
      footedWall(granite, [d.x(ye) + d.l, ye], [d.x(ye) + d.r, ye], gnd, () => d.z(ye) - 0.3, [0, 1, 0], 3)
      // Bents: a cap beam across and two columns to the ground.
      for (const y of st(d.y0 + 26, d.y1 - 12, 36).slice(0, -1)) {
        const x0 = d.x(y) + d.l + 0.8, x1 = d.x(y) + d.r - 0.8, zb = bot(y)
        if (zb - gnd(d.x(y), y) < 2) continue
        if (D) {
          box(granite, x0 - 0.6, x1 + 0.6, y - 0.7, y + 0.7, zb - 1.2, zb, true)
          for (const xc of [x0 + 0.5, x1 - 0.5]) footedLoft(granite, gnd, [
            { plan: chamferedRect(xc - 0.6, xc + 0.6, y - 0.6, y + 0.6, 0), z: 'ground' },
            { plan: chamferedRect(xc - 0.6, xc + 0.6, y - 0.6, y + 0.6, 0), z: zb - 1.2 },
          ], 10, false)
        } else footedWall(granite, [x0 - 0.6, y], [x1 + 0.6, y], gnd, () => zb, [0, 1, 0], 6) // low: the bent as one slab
      }
    }
  }

  // ---- Street lamps on both parapets -------------------------------------------------------------------------
  for (const y of st(END_W + 20, ET, D ? 18 : 36)) for (const s of SIDES) {
    const u = XC + s * ((y < WT ? AH : DH) - 0.3), z = road(y) + 6.2
    bead(lamps, [u, y, z], D ? 0.45 : 0.6, !D)
    if (D) rod(steel, [u, y, road(y) + 1.1], [u, y, z - 0.4], 0.09, 3)
  }

  return { stone, granite, steel, brick, shade, lamps }
}

const STONE: MaterialSpec = { ...finish('eads-limestone', 0xe0cfa8), doubleSided: true }
const GRANITE: MaterialSpec = { ...finish('eads-granite', 0xaaa69e), doubleSided: true }
const STEEL: MaterialSpec = { ...finish('eads-steel', 0x6f4b3e), doubleSided: true }
const BRICK: MaterialSpec = { ...finish('eads-brick', 0xb5654c), doubleSided: true }
const SHADE: MaterialSpec = { ...finish('eads-shade', 0x4f4b48), doubleSided: true }
const LAMP: MaterialSpec = { name: 'lamp', color: 0x3c3a38 }

async function main() {
  const extras = {
    license: 'CC0-1.0', frame: 'Y up, -Z north, +X east, metres; origin at the OSM outline centroid, on the river (117.75 m NAVD88)',
    bearing: 97.75, elevation: 0, deckCentre: XC, piers: { westAbutment: WA, west: WP, east: EP, eastAbutment: EA }, towers: [WT, ET],
    roadway: { landingWest: road(END_W), secondStreet: road(-512.5), crest: road(-15), split: road(264), landingNorth: roadN(628), landingSouth: roadS(628) },
    rail: { underDeck: `road - ${RAIL_DROP}`, eastDeck: railE(500), landing: railE(775) },
  }
  for (const [file, D, maxTris, maxBytes] of [
    ['stl-eads-bridge.glb', false, 6500, 250 * 1024],
    ['stl-eads-bridge.detail.glb', true, 40000, 1536 * 1024],
  ] as const) {
    const p = build(D)
    const parts = [
      { part: p.stone, material: STONE }, { part: p.granite, material: GRANITE }, { part: p.steel, material: STEEL },
      { part: p.brick, material: BRICK }, { part: p.shade, material: SHADE }, { part: p.lamps, material: LAMP },
    ]
    console.log(parts.map((q) => `${q.material.name} ${q.part.triangles}`).join(', '))
    const tris = parts.reduce((n, { part }) => n + part.triangles, 0)
    if (tris > maxTris) throw new Error(`${file}: ${tris} triangles, over ${maxTris}`)
    const glb = writeGlb('Eads Bridge', parts, extras)
    if (glb.length > maxBytes) throw new Error(`${file}: ${glb.length} bytes, over ${maxBytes}`)
    await Bun.write(new URL(`../models/${file}`, import.meta.url), glb)
    console.log(`${file}: ${tris} triangles, ${glb.length} bytes`)
  }
}

if (import.meta.main) await main()
